int R=0, w=0;
Letter buffer[N];
semaphore mutex=1, empty=N, full=0;
void writer() {
    do{
        write a letter in next;
        wait(empty);
        wait(mutex);
        buffer[N]=next;
        w=(w+1)%N;
        signal(mutex);
        signal(full);
    }while(True)
}
void Reader(){
    do{
        wait(full);
        wait(mutex);
        nextc=buffer[N];
        R=(R+1)%N;
        signal(mutex);
        signal(empty);
    }while(True)
}
void main(){
    cobegin{
        writer(); Reader()
    }
    coend
}

